    @Bean
    public RouteLocator routes(RouteLocatorBuilder builder) {
        return builder.routes()
                // Dummy route
                .route("path_route", r -> r
                        .path("/get")
                        .filters(f -> f
                                .requestRateLimiter(c -> {
                                    c.setRateLimiter(standardRateLimiter);
                                    c.setKeyResolver(keyResolver);
                                }))
                        .uri("https://httpbin.org"))
                // Auth route — strict tier
                .route("auth_route", r -> r
                        .path("/auth/**")
                        .filters(f -> f
                                .requestRateLimiter(c -> {
                                    c.setRateLimiter(authRateLimiter);
                                    c.setKeyResolver(keyResolver);
                                }))
                        .uri("lb://AUTH-SERVICE"))
                // Products route
                .route("products_route", r -> r
                        .path("/api/products/**")
                        .filters(f -> f
                                .requestRateLimiter(c -> {
                                    c.setRateLimiter(standardRateLimiter);
                                    c.setKeyResolver(keyResolver);
                                }))
                        .uri("lb://PRODUCT-SERVICE"))
                // Cart route — tokenRelay forwards the JWT so cart-service can validate ownership
                .route("cart_route", r -> r
                        .path("/api/cart/**")
                        .filters(f -> f
                                .tokenRelay()
                                .requestRateLimiter(c -> {
                                    c.setRateLimiter(standardRateLimiter);
                                    c.setKeyResolver(keyResolver);
                                }))
                        .uri("lb://CART-SERVICE"))
                // Order route — preserves tokenRelay for JWT propagation
                .route("order_route", r -> r
                        .path("/api/orders/**")
                        .filters(f -> f
                                .tokenRelay()
                                .requestRateLimiter(c -> {
                                    c.setRateLimiter(standardRateLimiter);
                                    c.setKeyResolver(keyResolver);
                                }))
                        .uri("lb://ORDER-SERVICE"))
                // Notification route
                .route("notification_route", r -> r
                        .path("/api/notification/**")
                        .filters(f -> f
                                .requestRateLimiter(c -> {
                                    c.setRateLimiter(standardRateLimiter);
                                    c.setKeyResolver(keyResolver);
                                }))
                        .uri("lb://NOTIFICATION-SERVICE"))
                .build();
    }
}

