package com.ecommerce.order_service.controller;

import com.ecommerce.order_service.dto.OrderDetailResponse;
import com.ecommerce.order_service.dto.OrderRequest;
import com.ecommerce.order_service.dto.OrderResponse;
import com.ecommerce.order_service.dto.OrderSummaryResponse;
import com.ecommerce.order_service.service.OrderService;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import org.springframework.http.HttpStatus;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.web.bind.annotation.*;

import java.util.List;

@RestController
@RequestMapping("/api/orders")
@RequiredArgsConstructor
public class OrderController {

    private final OrderService orderService;

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public OrderResponse placeOrder(@Valid @RequestBody OrderRequest orderRequest, @AuthenticationPrincipal Jwt jwt) {
        String userId = jwt.getSubject();
        String userEmail = jwt.getClaimAsString("email");
        return orderService.placeOrder(userId, userEmail, orderRequest.idempotencyKey());
    }

    @GetMapping("/my")
    public List<OrderSummaryResponse> getMyOrders(@AuthenticationPrincipal Jwt jwt) {
        return orderService.getOrdersByUserId(jwt.getSubject());
    }

    @GetMapping("/{orderId}")
    public OrderDetailResponse getOrderDetail(@PathVariable Long orderId, @AuthenticationPrincipal Jwt jwt) {
        return orderService.getOrderDetail(orderId, jwt.getSubject());
    }

}

