@Service
@RequiredArgsConstructor
@Slf4j
public class EmailService {

    private final JavaMailSender javaMailSender;

    @Value("${spring.mail.username:no-reply@ecommerce.com}")
    private String fromEmail;

    /**
     * Sends an HTML formatted email to the customer.
     */
    public void sendOrderConfirmation(String toEmail, String orderReference) {
        log.info("Preparing to send order confirmation to: {}", toEmail);

        try {
            MimeMessage message = javaMailSender.createMimeMessage();
            MimeMessageHelper helper = new MimeMessageHelper(message, true, "UTF-8");

            helper.setFrom(fromEmail);
            helper.setTo(toEmail);
            helper.setSubject("Order Confirmation - " + orderReference);

            // Simple HTML Template
            String htmlContent = String.format("""
                <div style="font-family: Arial, sans-serif; padding: 20px; color: #333;">
                    <h1 style="color: #000;">Order Received!</h1>
                    <p>Thank you for your purchase.</p>
                    <div style="background: #f4f4f4; padding: 15px; border-radius: 5px; margin: 20px 0;">
                        <p style="margin: 0; font-size: 14px; color: #666;">Order Reference:</p>
                        <p style="margin: 5px 0 0; font-size: 24px; font-weight: bold; color: #000;">%s</p>
                    </div>
                    <p>We are processing your order and will notify you when it ships.</p>
                    <br/>
                    <p style="font-size: 12px; color: #999;">The E-Commerce Team</p>
                </div>
                """, orderReference);

            helper.setText(htmlContent, true);

            javaMailSender.send(message);
            log.info("Email sent successfully to {}", toEmail);

        } catch (MessagingException e) {
            throw new RuntimeException("Email delivery failed for order: " + orderReference, e);
        }
    }
}
