@Component
@RequiredArgsConstructor
@Slf4j
public class OrderProducer {

    private final RabbitTemplate rabbitTemplate;

    /**
     * Publishes an order placement event to RabbitMQ.
     */
    public void sendOrderConfirmation(OrderPlacedEvent event) {
        log.info("Publishing OrderPlacedEvent to RabbitMQ for Order Ref: {}", event.orderReference());

        try {
            rabbitTemplate.convertAndSend(
                    RabbitMQConfig.EXCHANGE,
                    RabbitMQConfig.ROUTING_KEY,
                    event
            );
            log.info("Successfully published event for Order: {}", event.orderReference());
        } catch (Exception e) {
            log.error("Failed to publish order event to RabbitMQ: {}", e.getMessage());
            // In a production app, you might implement a retry mechanism or Outbox pattern here
        }
    }
}
