package com.ecommerce.api_gateway.config;

import org.springframework.cloud.gateway.filter.ratelimit.KeyResolver;
import org.springframework.cloud.gateway.filter.ratelimit.RedisRateLimiter;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Primary;
import reactor.core.publisher.Mono;

@Configuration
public class RateLimiterConfig {

    /**
     * Resolves a rate-limit key from the request:
     *  1. Authenticated principal name (JWT subject)
     *  2. Client remote IP address
     *  3. "unknown" as a final fallback
     */
    @Bean
    @Primary
    public KeyResolver keyResolver() {
        return exchange -> exchange.getPrincipal()
                .map(principal -> principal.getName())
                .switchIfEmpty(Mono.defer(() -> Mono.justOrEmpty(exchange.getRequest().getRemoteAddress())
                        .map(addr -> addr.getAddress().getHostAddress())))
                .defaultIfEmpty("unknown");
    }

    /** Strict limiter for /auth/** — burst aligned with Keycloak failureFactor=5. */
    @Bean
    public RedisRateLimiter authRateLimiter() {
        return new RedisRateLimiter(3, 5);
    }

    /** Standard limiter for all other routes. @Primary satisfies RequestRateLimiterGatewayFilterFactory's default injection. */
    @Bean
    @Primary
    public RedisRateLimiter standardRateLimiter() {
        return new RedisRateLimiter(20, 40);
    }
}

