    @Test
    void rateLimiter_exceedingLimit_returns429() {
        // With burstCapacity=1 and replenishRate=1, the second immediate request must be rate-limited
        webTestClient.get().uri("/api/products/test")
                .exchange()
                .expectStatus().isOk();

        webTestClient.get().uri("/api/products/test")
                .exchange()
                .expectStatus().isEqualTo(HttpStatus.TOO_MANY_REQUESTS);
    }

    @TestConfiguration
    static class IntegrationTestConfig {

        /** Permit all, no OAuth2 — keeps the test context self-contained. */
        @Bean
        SecurityWebFilterChain testSecurityFilterChain(ServerHttpSecurity http) {
            return http
                    .csrf(ServerHttpSecurity.CsrfSpec::disable)
                    .authorizeExchange(ex -> ex.anyExchange().permitAll())
                    .build();
        }

        /**
         * Overrides the production standardRateLimiter bean (by name) with a 1 req/s limit
         * so the test can trigger 429 on the second request.
         * Requires spring.main.allow-bean-definition-overriding=true.
         */
        @Bean
        @Primary
        RedisRateLimiter standardRateLimiter() {
            return new RedisRateLimiter(1, 1);
        }

        /** Single test route pointing to WireMock — avoids lb:// Eureka dependency. */
        @Bean
        RouteLocator routes(RouteLocatorBuilder builder,
                                      KeyResolver keyResolver,
                                      @Qualifier("standardRateLimiter") RedisRateLimiter standardRateLimiter) {
            return builder.routes()
                    .route("test_products_route", r -> r
                            .path("/api/products/**")
                            .filters(f -> f
                                    .requestRateLimiter(c -> {
                                        c.setRateLimiter(standardRateLimiter);
                                        c.setKeyResolver(keyResolver);
                                    }))
                            .uri("http://localhost:" + wireMock.port()))
                    .build();
        }
    }
}

