@Component({
  selector: 'app-checkout',
  imports: [CommonModule, RouterModule],
  templateUrl: './checkout.html',
  styleUrl: './checkout.scss',
})
export class Checkout {
  private authService = inject(Auth);
  userInfo = this.authService.currentUser();

  private router = inject(Router);
  paymentMethod = signal('cc');

  private cartService = inject(CartService);
  cart = this.cartService.cart;

  orderService = inject(OrderService);

  private notificationService = inject(Notification);

  placeOrder() {
    const existing = sessionStorage.getItem(IDEMPOTENCY_KEY);
    const idempotencyKey = existing || generateUUID();
    if (!existing) {
      sessionStorage.setItem(IDEMPOTENCY_KEY, idempotencyKey);
    }

    this.orderService.isCheckoutProcessing.set(true);

    this.orderService
      .checkout(this.userInfo?.id, idempotencyKey)
      .pipe(finalize(() => {
        this.orderService.isCheckoutProcessing.set(false);
        this.cartService.refreshCart().subscribe();
      }))
      .subscribe({
        next: (result) => {
          sessionStorage.removeItem(IDEMPOTENCY_KEY);
          this.router.navigate(['/order-success'], {
            state: { orderResponse: result },
          });
        },
        error: (err) => {
          console.error('Checkout Error:', err);
          this.notificationService.show('Failed to place order. Please try again.', 'error');
        },
      });
  }

}

