package com.ecommerce.api_gateway.client;

import com.ecommerce.api_gateway.dto.UserProfileResponse;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.cloud.client.circuitbreaker.ReactiveCircuitBreaker;
import org.springframework.cloud.client.circuitbreaker.ReactiveCircuitBreakerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.security.core.context.ReactiveSecurityContextHolder;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.stereotype.Component;
import org.springframework.web.reactive.function.client.WebClient;
import org.springframework.web.server.ResponseStatusException;
import reactor.core.publisher.Mono;

@Component
public class AuthClient {

    private final WebClient webClient;
    private final ReactiveCircuitBreaker circuitBreaker;

    @Value("${services.auth-service.users-uri}")
    private String authUsersUri;

    @SuppressWarnings("rawtypes")
    public AuthClient(WebClient.Builder builder, ReactiveCircuitBreakerFactory factory) {
        this.webClient = builder.build();
        this.circuitBreaker = factory.create("auth-service");
    }

    public Mono<UserProfileResponse> getMyProfile() {
        return ReactiveSecurityContextHolder.getContext()
                .map(ctx -> (Jwt) ctx.getAuthentication().getCredentials())
                .flatMap(jwt ->
                        webClient.get()
                                .uri(authUsersUri + "/" + jwt.getSubject())
                                .retrieve()
                                .bodyToMono(UserProfileResponse.class)
                                .transform(mono -> circuitBreaker.run(mono,
                                        t -> Mono.error(new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE, "auth-service unavailable"))))
                );
    }
}

