package com.ecommerce.api_gateway.config;

import io.netty.channel.ChannelOption;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.client.reactive.ReactorClientHttpConnector;
import org.springframework.web.reactive.function.client.WebClient;
import reactor.netty.http.client.HttpClient;

@Configuration
public class WebClientConfig {

    @Bean
    public WebClient.Builder webClientBuilder() {
        // responseTimeout is intentionally omitted: Resilience4j timelimiter is the
        // authoritative read timeout. Running both at the same duration causes a race
        // where the circuit-breaker subscriber delivers a response while simultaneously
        // cancelling, resulting in AbortExecutionException in the GraphQL layer.
        HttpClient httpClient = HttpClient.create()
                .option(ChannelOption.CONNECT_TIMEOUT_MILLIS, 2_000);
        return WebClient.builder()
                .clientConnector(new ReactorClientHttpConnector(httpClient));
    }
}

