@Component
public class OrderClient {

    private final WebClient webClient;
    private final ReactiveCircuitBreaker circuitBreaker;

    @Value("${services.order-service.uri}")
    private String orderServiceUri;

    @SuppressWarnings("rawtypes")
    public OrderClient(WebClient.Builder builder, ReactiveCircuitBreakerFactory factory) {
        this.webClient = builder.build();
        this.circuitBreaker = factory.create("order-service");
    }

    public Mono<OrderResponse> checkout(CheckoutInput input) {
        return ReactiveSecurityContextHolder.getContext()
                .map(ctx -> ctx.getAuthentication().getCredentials())
                .cast(Jwt.class)
                .flatMap(jwt ->
                        webClient.post()
                                .uri(orderServiceUri)
                                .header("Authorization", "Bearer " + jwt.getTokenValue())
                                .bodyValue(input)
                                .retrieve()
                                .bodyToMono(OrderResponse.class)
                                .transform(mono -> circuitBreaker.run(mono,
                                        t -> Mono.error(new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE, "order-service unavailable"))))
                );
    }

    public Mono<List<OrderSummaryResponse>> getMyOrders() {
        return ReactiveSecurityContextHolder.getContext()
                .map(ctx -> ctx.getAuthentication().getCredentials())
                .cast(Jwt.class)
                .flatMap(jwt ->
                        webClient.get()
                                .uri(orderServiceUri + "/my")
                                .header("Authorization", "Bearer " + jwt.getTokenValue())
                                .retrieve()
                                .bodyToFlux(OrderSummaryResponse.class)
                                .transform(flux -> circuitBreaker.run(flux,
                                        t -> Flux.error(new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE, "order-service unavailable"))))
                                .collectList()
                );
    }

