import org.springframework.amqp.rabbit.annotation.RabbitListener;
import org.springframework.stereotype.Component;

@Component
@RequiredArgsConstructor
@Slf4j
public class OrderConsumer {

    private final EmailService emailService;

    /**
     * This method is triggered automatically whenever a message
     * arrives in the 'order.placed.queue'.
     */
    @RabbitListener(queues = RabbitMQConfig.QUEUE)
    public void consumeOrderPlacedEvent(OrderPlacedEvent event) {
        log.info("Notification Received!");
        log.info("Processing order reference: {}", event.orderReference());
        log.info("Sending confirmation email to: {}", event.email());

        // Call the email service to handle the send order confirmation
        emailService.sendOrderConfirmation(event.email(), event.orderReference());
    }
}
