@Injectable({
  providedIn: 'root',
})
export class OrderService {
  private apollo = inject(Apollo);

  readonly isCheckoutProcessing = signal(false);

  checkout(userId: string, idempotencyKey: string): Observable<OrderResponse> {
    return this.apollo
      .mutate<{ checkout: OrderResponse }>({
        mutation: CHECKOUT_MUTATION,
        variables: {
          input: {
            userId,
            idempotencyKey,
          }
        },
      })
      .pipe(map((result) => result.data?.checkout as OrderResponse));
  }

  getMyOrders(): Observable<OrderSummary[]> {
    return this.apollo
      .query<{ myOrders: OrderSummary[] }>({
        query: MY_ORDERS_QUERY,
        fetchPolicy: 'network-only',
      })
      .pipe(map((result) => result.data?.myOrders ?? []));
  }

  getOrderDetail(orderId: string): Observable<OrderDetail> {
    return this.apollo
      .query<{ orderDetail: OrderDetail }>({
        query: ORDER_DETAIL_QUERY,
        variables: { orderId },
        fetchPolicy: 'network-only',
      })
      .pipe(map((result) => result.data?.orderDetail as OrderDetail));
  }
}

