@Controller
@RequiredArgsConstructor
public class OrderGraphQLController {

    private final OrderClient orderClient;
    private final ProductClient productClient;

    @MutationMapping
    public Mono<OrderResponse> checkout(@Valid @Argument CheckoutInput input) {
        return orderClient.checkout(input);
    }

    @QueryMapping
    public Mono<List<OrderSummaryResponse>> myOrders() {
        return orderClient.getMyOrders();
    }

    @QueryMapping
    public Mono<OrderDetailResponse> orderDetail(@Argument Long orderId) {
        return orderClient.getOrderDetail(orderId);
    }

    @SchemaMapping(typeName = "OrderLineItem", field = "productName")
    public Mono<String> getProductName(OrderLineItemResponse item) {
        if (item.productName() != null && !item.productName().isBlank()) {
            return Mono.just(item.productName());
        }
        return productClient.getProductName(item.productId());
    }

    @SchemaMapping(typeName = "OrderLineItem", field = "imageUrl")
    public Mono<String> getImageUrl(OrderLineItemResponse item) {
        if (item.imageUrl() != null && !item.imageUrl().isBlank()) {
            return Mono.just(item.imageUrl());
        }
        return productClient.getImageUrl(item.productId());
    }

}

