    public Mono<Cart> addToCart(String userId, String productId, int quantity) {
        Mono<ProductResponse> productMono = webClient.get()
                .uri(productServiceUri + "/{id}", productId)
                .retrieve()
                .onStatus(status -> status.isError(), response ->
                        Mono.error(new ResponseStatusException(HttpStatus.NOT_FOUND, "Product not found in Catalog")))
                .bodyToMono(ProductResponse.class);

        return productCircuitBreaker.run(productMono,
                        t -> Mono.error(new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE, "Product service unavailable")))
                .flatMap(product -> Mono.fromCallable(() -> {
                    Cart cart = cartRepository.findById(userId).orElse(new Cart(userId));
                    cart.getItems().stream()
                            .filter(item -> item.getProductId().equals(product.id()))
                            .findFirst()
                            .ifPresentOrElse(
                                    existing -> existing.setQuantity(existing.getQuantity() + quantity),
                                    () -> cart.getItems().add(new CartItem(product.id(), quantity))
                            );
                    return cartRepository.save(cart);
                }).subscribeOn(Schedulers.boundedElastic()));
    }

    public Mono<Cart> removeItem(String userId, String productId) {
        return Mono.fromCallable(() -> {
            Cart cart = cartRepository.findById(userId).orElse(new Cart(userId));
            cart.getItems().removeIf(item -> item.getProductId().equals(productId));
            return cartRepository.save(cart);
        }).subscribeOn(Schedulers.boundedElastic());
    }

