@Slf4j
@Component
@RequiredArgsConstructor
public class DataLoader implements CommandLineRunner {

    private final ProductRepository productRepository;

    @Override
    public void run(String... args) throws Exception {
        // Only load data if the database is empty to prevent duplicates
        if (productRepository.count() < 1) {
            Product product1 = Product.builder()
                    .name("iPhone 15")
                    .description("Latest Apple smartphone")
                    .price(new BigDecimal("999.99"))
                    .stockQuantity(100)
                    .category("Smartphone")
                    .imageUrl("/product-images/iphone-15.png")
                    .build();

            Product product2 = Product.builder()
                    .name("MacBook Pro")
                    .description("M3 Pro Chip, 16GB RAM")
                    .price(new BigDecimal("1999.99"))
                    .stockQuantity(50)
                    .category("Laptop")
                    .imageUrl("/product-images/macbook-pro-14-m3.png")
                    .build();

            Product product3 = Product.builder()
                    .name("Sony WH-1000XM5")
                    .description("Noise cancelling headphones")
                    .price(new BigDecimal("349.99"))
                    .stockQuantity(0)
                    .category("Audio")
                    .build();

            Product product4 = Product.builder()
                    .name("Samsung Galaxy S24 Ultra")
                    .description("Flagship Android smartphone with AI features and S-Pen")
                    .price(new BigDecimal("699.99"))
                    .stockQuantity(75)
                    .category("Smartphone")
                    .imageUrl("/product-images/samsung-galaxy-s24-ultra.png")
                    .build();

            productRepository.saveAll(List.of(product1, product2, product3, product4));
            log.info("Database seeded with initial product data");
        } else {
            log.info("Database already contains data, skipping seed");
        }
    }
}

